import { z } from 'zod';

export const MAX_FIELDS = 50;

/*
 * Messages are shown to recruiters in the form builder, next to the setting
 * they describe. Ids are generated by the builder, so a bad one means a bug
 * or a stale page rather than something to fix by typing.
 */
const RELOAD = 'Something went wrong with this form. Reload the page and try again.';

/** A whole number from `min` to `max`, with one message for every way it can fail. */
function wholeNumber(min: number, max: number, error: string) {
  return z.number({ error }).int({ error }).min(min, { error }).max(max, { error });
}

const optionsSchema = z
  .array(
    z.object({
      id: z.uuid({ error: RELOAD }),
      label: z
        .string()
        .trim()
        .min(1, { error: 'Give this option a label.' })
        .max(100, { error: 'Option labels must be 100 characters or fewer.' }),
    }),
  )
  .min(2, { error: 'Add at least 2 options.' })
  .max(50, { error: 'A question can have at most 50 options.' });

/** Properties every field has, whatever its type. */
const base = {
  key: z.uuid({ error: RELOAD }),
  label: z
    .string()
    .trim()
    .min(1, { error: 'Write the question.' })
    .max(200, { error: 'Questions must be 200 characters or fewer.' }),
  helpText: z
    .string()
    .trim()
    .max(500, { error: 'Help text must be 500 characters or fewer.' })
    .nullable(),
  required: z.boolean(),
};

const shortText = z.object({
  ...base,
  type: z.literal('short_text'),
  config: z.object({
    maxLength: wholeNumber(1, 500, 'Set an answer limit from 1 to 500 characters.'),
  }),
});

const longText = z.object({
  ...base,
  type: z.literal('long_text'),
  config: z.object({
    maxLength: wholeNumber(1, 10000, 'Set an answer limit from 1 to 10,000 characters.'),
  }),
});

const singleSelect = z.object({
  ...base,
  type: z.literal('single_select'),
  config: z.object({
    options: optionsSchema,
    /** Choosing one of these rejects the application automatically. */
    rejectOptionIds: z.array(z.uuid({ error: RELOAD })),
  }),
});

const multiSelect = z.object({
  ...base,
  type: z.literal('multi_select'),
  config: z.object({
    options: optionsSchema,
    maxSelections: z
      .number()
      .int({ error: 'The selection limit must be a whole number.' })
      .min(1, { error: 'Allow at least 1 selection.' })
      .nullable(),
  }),
});

const yesNo = z.object({
  ...base,
  type: z.literal('yes_no'),
  config: z.object({
    /** The answer that rejects the application, or null for no knockout. */
    rejectWhen: z.boolean().nullable(),
  }),
});

const file = z.object({
  ...base,
  type: z.literal('file'),
  config: z.object({
    allowedTypes: z
      .array(z.enum(['pdf', 'image', 'document'], { error: RELOAD }))
      .min(1, { error: 'Choose at least one file type.' }),
    maxSizeMb: wholeNumber(1, 25, 'Set a file size limit from 1 to 25 MB.'),
  }),
});

export const formFieldSchema = z.discriminatedUnion('type', [
  shortText,
  longText,
  singleSelect,
  multiSelect,
  yesNo,
  file,
]);

export type FormField = z.infer<typeof formFieldSchema>;
export type FormFieldType = FormField['type'];

export const formFieldsSchema = z
  .array(formFieldSchema)
  .max(MAX_FIELDS, { error: `A form can have at most ${MAX_FIELDS} questions.` })
  .superRefine((fields, ctx) => {
    const keys = new Set<string>();

    fields.forEach((field, index) => {
      if (keys.has(field.key)) {
        ctx.addIssue({ code: 'custom', message: RELOAD, path: [index, 'key'] });
      }
      keys.add(field.key);

      if (field.type !== 'single_select' && field.type !== 'multi_select') {
        return;
      }

      const optionIds = new Set(field.config.options.map((option) => option.id));
      if (optionIds.size !== field.config.options.length) {
        ctx.addIssue({
          code: 'custom',
          message: RELOAD,
          path: [index, 'config', 'options'],
        });
      }

      if (field.type === 'single_select') {
        const unknown = field.config.rejectOptionIds.some((id) => !optionIds.has(id));
        if (unknown) {
          ctx.addIssue({
            code: 'custom',
            message: 'An auto-reject rule points to an option that no longer exists. Update the rule.',
            path: [index, 'config', 'rejectOptionIds'],
          });
        }
      }

      if (
        field.type === 'multi_select' &&
        field.config.maxSelections !== null &&
        field.config.maxSelections > field.config.options.length
      ) {
        ctx.addIssue({
          code: 'custom',
          message: "The selection limit can't be more than the number of options.",
          path: [index, 'config', 'maxSelections'],
        });
      }
    });
  });

export type FormFields = z.infer<typeof formFieldsSchema>;

export interface FieldError {
  /** Where the problem is, such as "2.config.options". */
  path: string;
  message: string;
}

export type ParseResult =
  | { ok: true; fields: FormFields }
  | { ok: false; errors: FieldError[] };

/** Validates a field list from an untrusted source. */
export function parseFormFields(input: unknown): ParseResult {
  const result = formFieldsSchema.safeParse(input);
  if (result.success) {
    return { ok: true, fields: result.data };
  }
  return {
    ok: false,
    errors: result.error.issues.map((issue) => ({
      path: issue.path.join('.'),
      message: issue.message,
    })),
  };
}